BEGIN;
SELECT customer_id AS closing_customer FROM private.customer_relations WHERE membership_id='00000000-0000-4000-b000-000000000205' AND relation_type='identity' AND revoked_at IS NULL LIMIT 1 \gset
SELECT test.assert_true(NOT has_table_privilege('authenticated','private.account_closures','SELECT,INSERT,UPDATE,DELETE'),'closure: private reason and archive');
SELECT test.assert_true(NOT has_function_privilege('anon','public.account_close(uuid,jsonb)','EXECUTE'),'closure: anonymous denied');
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000201","session_id":"00000000-0000-4000-c000-000000000201"}';
SELECT test.expect_error($q$SELECT public.account_close('00000000-0000-4000-e000-000000000201','{"reason":"privacy","observation":"","acknowledged":true,"export_offered":true}')$q$,'PT403','closure: staff cannot use client closure');
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000205","session_id":"00000000-0000-4000-c000-000000000205"}';
SELECT test.expect_error($q$SELECT public.account_close('00000000-0000-4000-e000-000000000202','{"reason":"privacy","observation":"","acknowledged":true,"export_offered":true}')$q$,'PT403','closure: other office denied');
SELECT test.expect_error($q$SELECT public.account_close('00000000-0000-4000-e000-000000000201','{"reason":"privacy","observation":"","acknowledged":false,"export_offered":true}')$q$,'PT422','closure: legal acknowledgement required');
SELECT test.expect_error($q$SELECT public.account_close('00000000-0000-4000-e000-000000000201','{"reason":["privacy","unused"],"observation":"","acknowledged":true,"export_offered":true}')$q$,'PT422','closure: exactly one reason');
SELECT test.assert_true(jsonb_typeof(public.account_export_manifest('00000000-0000-4000-e000-000000000201')->'ids')='array','closure: own authorized manifest supports empty');
RESET ROLE;
CREATE TEMP TABLE before_closure AS SELECT (SELECT count(*) FROM public.requests) requests,(SELECT count(*) FROM private.document_publications) documents,(SELECT count(*) FROM private.payments) payments;
SET ROLE authenticated;
SELECT test.assert_true(public.account_close('00000000-0000-4000-e000-000000000201','{"reason":"privacy","observation":"Sensitive optional text","acknowledged":true,"export_offered":true}')->>'closed'='true','closure: transactional completion');
SELECT test.expect_error($q$SELECT public.account_export_manifest('00000000-0000-4000-e000-000000000201')$q$,'PT401','closure: current session cannot export');
SELECT test.expect_error($q$SELECT public.session_activity(false)$q$,'PT401','closure: current session denied');
RESET ROLE;
SELECT test.assert_true(NOT EXISTS(SELECT FROM public.memberships WHERE user_id='00000000-0000-4000-a000-000000000205' AND active),'closure: every membership disabled');
SELECT test.assert_true((SELECT observation IS NULL FROM private.account_closures WHERE user_id='00000000-0000-4000-a000-000000000205'),'closure: dispensable observation eliminated immediately');
SELECT test.assert_true((SELECT (SELECT count(*) FROM public.requests)=requests AND(SELECT count(*) FROM private.document_publications)=documents AND(SELECT count(*) FROM private.payments)=payments FROM before_closure),'closure: FK business history and money preserved');
SELECT test.expect_error($q$UPDATE public.memberships SET active=true WHERE user_id='00000000-0000-4000-a000-000000000205'$q$,'PT403','closure: management cannot reactivate closed UID');
INSERT INTO auth.sessions(id,user_id)VALUES('00000000-0000-4000-c000-000000009999','00000000-0000-4000-a000-000000000205');
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000205","session_id":"00000000-0000-4000-c000-000000009999"}';
SELECT test.expect_error($q$SELECT public.session_activity(false)$q$,'PT401','closure: newly issued provider session cannot login');
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000201","session_id":"00000000-0000-4000-c000-000000000201"}';
SELECT test.assert_true(public.deleted_accounts_page('00000000-0000-4000-e000-000000000201','',1)->>'total'='1','closure: authorized archive consult');
SELECT test.assert_true(NOT EXISTS(SELECT FROM jsonb_array_elements(public.customers_page('00000000-0000-4000-e000-000000000201','',1,5)->'items') x WHERE x->>'id'=:'closing_customer'),'closure: deleted customer absent from ordinary client search');
SELECT test.assert_true(NOT EXISTS(SELECT FROM jsonb_array_elements(public.request_options('00000000-0000-4000-e000-000000000201','customers','',1,5)->'items') x WHERE x->>'id'=:'closing_customer'),'closure: deleted customer absent from request selection');
SELECT test.assert_true(NOT EXISTS(SELECT FROM jsonb_array_elements(public.document_options('00000000-0000-4000-e000-000000000201','customers',NULL,'',1)->'items') x WHERE x->>'id'=:'closing_customer'),'closure: deleted customer absent from document selection');
SELECT test.assert_true(NOT EXISTS(SELECT FROM jsonb_array_elements(public.customer_relation_candidates('00000000-0000-4000-e000-000000000201','customers','')->'items') x WHERE x->>'id'=:'closing_customer'),'closure: deleted customer absent from relationship selection');
SELECT test.assert_true(jsonb_typeof(public.deleted_account_documents('00000000-0000-4000-e000-000000000201','00000000-0000-4000-a000-000000000205')->'items')='array','closure: archive gates evaluated');
RESET ROLE;
ROLLBACK;
